import{_ as a,c as e,d as r,Z as l}from"./chunks/framework.B0uuYL3Y.js";const m=JSON.parse('{"title":"用计时和计数器分析访存","description":"从公开数组求和的对照出发，区分计时、PMU 事件计数、缓存层次归因和统计判断。","frontmatter":{"title":"用计时和计数器分析访存","description":"从公开数组求和的对照出发，区分计时、PMU 事件计数、缓存层次归因和统计判断。","date":"2026-11-25","tags":["微架构安全","测量方法","PMU","缓存","TLB"],"book":"microarch-00-intro"},"headers":[],"relativePath":"posts/microarch-04a-measurement.md","filePath":"posts/microarch-04a-measurement.md"}'),d={name:"posts/microarch-04a-measurement.md"};function i(s,t,h,n,o,c){return e(),r("div",null,t[0]||(t[0]=[l('<p>同一个数组求和程序，顺序版本比乱序版本快。两者读过同样的元素并算出了同样的和。差值可能来自缓存命中，也可能来自预取、页表遍历或发出的请求能否重叠。本文追问一件具体的事：<strong>一组时间和计数，究竟可以把差异归因到哪一步？</strong></p><p>贯穿全文的是两个只处理公开数据的程序版本。一个按索引递增顺序读取数组，另一个按预先准备好的排列读取同一批元素。假设元素均为非负整数，总和不溢出。所有表格都是构造数据，用于练习推理，事件名称为语义描述。真实测量需要按机器的事件表核对。先修知识是<a href="./microarch-01a-mshr.html">缓存时序</a>、<a href="./microarch-02-prefetch.html#prefetch-feedback">硬件预取</a>和 <a href="./microarch-02a-translation.html#sv39-tlb">TLB</a>。</p><nav class="table-of-contents"><ul><li><a href="#先说明这次计时量的是哪个对象">先说明这次计时量的是哪个对象</a></li><li><a href="#pmu-要按产生事件的地方来读">PMU 要按产生事件的地方来读</a></li><li><a href="#一个完整的归因例题">一个完整的归因例题</a></li><li><a href="#阈值判断要带上分母">阈值判断要带上分母</a></li><li><a href="#参考文献">参考文献</a></li></ul></nav><h2 id="先说明这次计时量的是哪个对象" tabindex="-1">先说明这次计时量的是哪个对象 <a class="header-anchor" href="#先说明这次计时量的是哪个对象" aria-label="Permalink to &quot;先说明这次计时量的是哪个对象&quot;">​</a></h2><p>整个求和循环的用时是一批工作完成的耗时。循环中如果有多个互相独立的加载，多个请求可以重叠。把总时间除以加载数，得到的是批量工作中的平均单位成本，里面包含重叠执行的影响。例如每次未命中响应需 90 个周期，若三个请求可以一起发出并一起返回，这三个响应阶段合计约等 90 个周期，而单条的响应延迟仍可能是 90 个周期。</p><p>还需要明确用的时间基准。墙钟时间会包含实验窗口中的调度等待。核心周期、参考周期和时钟读数有不同的计数规则。变频、线程迁移或抢占可能使它们的变化不一致。报告“快 20%”时，一并写清所用时间基准、统计区间、每次运行处理多少元素，以及所比较的是单次访问还是整段工作的完成时间。</p><p>顺序读取和乱序读取也能产生不同的机器指令。编译器可能向量化顺序循环，或者让乱序程序多执行一次索引加载。即使数据相同，实验也需要核对生成的代码和实际执行的工作。一个可比的思路是两个版本走同一个索引读取循环，只换索引数组内容，同时记录索引数组本身的访问代价。它控制了显著的指令差别，但仍需要关注数据依赖、缓存状态和重叠访存。</p><h2 id="pmu-要按产生事件的地方来读" tabindex="-1">PMU 要按产生事件的地方来读 <a class="header-anchor" href="#pmu-要按产生事件的地方来读" aria-label="Permalink to &quot;PMU 要按产生事件的地方来读&quot;">​</a></h2><p><strong>PMU</strong> 是处理器的性能监控单元。计数器被配置到某个事件之后，硬件在规定活动发生时累加。例题中最常混淆的是这些活动：</p><table tabindex="0"><thead><tr><th>想解释的对象</th><th>可关注的事件例子</th><th>仍需知道的范围</th></tr></thead><tbody><tr><td>程序做了多少架构工作</td><td>退休指令数</td><td>是哪个线程、核与特权范围，事件是否按 ISA 指令统计</td></tr><tr><td>某一级缓存发生了什么</td><td>只计需求加载的未命中，或统计该级缓存行填充</td><td>哪一级，是否合并，是否包括预取与未退休活动</td></tr><tr><td>翻译路径有没有变长</td><td>一级 DTLB 未命中、下级 TLB 命中、完成的页表遍历</td><td>记录的是开始还是结束，适用于何种地址翻译情况</td></tr><tr><td>请求在等什么</td><td>某类在途或阻塞周期</td><td>是否可能同时存在多个原因，事件能否被直接相加</td></tr></tbody></table><p>具体事件的限定条件来自该 CPU 型号的手册。一个叫“缓存未命中”的通用名字不能自行补齐这些细节。Linux 还可区分计数范围、排除用户态或内核态，以及在资源不足时轮换多个事件。记录测量权限和事件实际运行时间，读者才知道数值代表哪个窗口。</p><p>例如一个事件在 10 ms 的启用时间内实际运行 4 ms，计到 400。常用比例估算是 <code>400 × 10 / 4 = 1000</code>。如果程序的事件大多集中在某一短阶段，轮到计数器的 4 ms 未必代表整个 10 ms。比例换算得到的是基于采样窗口的估计。想认真比较两个强相关事件时，要检查它们是否同时运行、覆盖是否足够、实验会不会因反复或轮换而改变阶段组成。</p><h2 id="一个完整的归因例题" tabindex="-1">一个完整的归因例题 <a class="header-anchor" href="#一个完整的归因例题" aria-label="Permalink to &quot;一个完整的归因例题&quot;">​</a></h2><p>两个版本都走同一访问循环，处理同样数量的公开数组元素。每种条件重复多次，表中给出各条件的中位数，假设计数器都覆盖同样完整的测量区间。为了练习排查翻译的影响，分别比较普通页与大页。以下四行是<strong>构造数据</strong>，列名描述的是已经核对语义的教学计数。</p><table tabindex="0"><thead><tr><th>地址访问顺序</th><th>关联数据的页大小</th><th style="text-align:right;">时间</th><th style="text-align:right;">完成的页表遍历</th><th style="text-align:right;">数据需求加载的 L1 未命中</th></tr></thead><tbody><tr><td>顺序</td><td>普通页</td><td style="text-align:right;">120 μs</td><td style="text-align:right;">32</td><td style="text-align:right;">320</td></tr><tr><td>乱序</td><td>普通页</td><td style="text-align:right;">228 μs</td><td style="text-align:right;">190</td><td style="text-align:right;">520</td></tr><tr><td>顺序</td><td>大页</td><td style="text-align:right;">111 μs</td><td style="text-align:right;">2</td><td style="text-align:right;">340</td></tr><tr><td>乱序</td><td>大页</td><td style="text-align:right;">151 μs</td><td style="text-align:right;">3</td><td style="text-align:right;">510</td></tr></tbody></table><p>普通页下两个版本差 108 μs，大页下差 40 μs；遍历次数的差从 158 降到 1。可以支持的解读是：改变页大小后，遍历行为和时间差同时显著变化，翻译成本是值得进一步验证的解释。与此同时，L1 未命中仍然有不小差别。它可能与大页条件下残留的 40 μs 有关，但这张表还没给出从哪一级返回、请求重叠程度或预取效果。</p><p>很容易进一步写成“每次页表遍历固定花了 <code>68 μs / 157</code>”。这个结论还需要证明两个版本间的其他成本都不变，而且所有遍历都阻塞了程序的关键路径。大页还可能改变虚实布局、缓存组分布或预取所见的页边界，所以可以继续做更细的对照。测量前应分别准备可比较的缓存初态和翻译初态，并记录页大小是否确实生效。对有重复阶段的程序，可以交错运行 A、B，观察各轮差值的分布，排除总是先测某一方导致的初态偏差。</p><p>如果目标是确认“某些迟到的预取获益”，应找能够说明地址请求、在途合并或填充时序的证据。一个总缓存未命中计数可能保持不变，因为<a href="./microarch-02-prefetch.html#prefetch-fill">需求仍发生了 L1 未命中</a>，它只是更早拿到同一个下级响应。选择记录时，从假设的因果链倒推所需事件，比先收集许多同名计数更有效。</p><h2 id="阈值判断要带上分母" tabindex="-1">阈值判断要带上分母 <a class="header-anchor" href="#阈值判断要带上分母" aria-label="Permalink to &quot;阈值判断要带上分母&quot;">​</a></h2><p>另一个常见任务是用单次耗时区分本级有无可用数据。先通过独立方法准备两组已知的状态，在另一批样本上评估一个预先确定的阈值。下表仍是构造数据，每行 100 次：</p><table tabindex="0"><thead><tr><th>实际状态</th><th style="text-align:right;">判作数据在近处</th><th style="text-align:right;">判作需要下一层</th></tr></thead><tbody><tr><td>数据在近处</td><td style="text-align:right;">93</td><td style="text-align:right;">7</td></tr><tr><td>数据需要下一层</td><td style="text-align:right;">11</td><td style="text-align:right;">89</td></tr></tbody></table><p>将“在近处”视为阳性，假阳性率为 11%，假阴性率为 7%。把判据用于另外 1000 次读取，若只有 100 次确实在近处，并假定条件错误率保持不变，约有 93 次真正的近处访问落入阳性。其余 900 次会贡献约 99 次假阳性。阳性中的正判比例是 <code>93/(93+99)</code>，约 48%。这解释了为何在均衡验证样本上表现良好的判据，遇到稀少状态时仍会产生许多误判。</p><p>实际实验还应保留原始分布、训练和验证的分界、初态准备方法及重复结果。当“近处”的标签本身来自同一次计时，便会让证据绕回原点。独立的初态控制或事件验证能帮助打破这种循环。到这里可以回答“时间怎样支持一个分类”。接下来还要回答这个分类提供了关于什么的新信息。</p><details class="details custom-block"><summary>练习：相同的 L1 未命中是否意味着相同的等待</summary><p>两个版本各有 50 次 L1 需求未命中。A 中有 40 次在需求前已经由预取发出对应下级请求，需求到达后合并。B 中 50 次都要在需求到达后启动。两者的 L1 未命中计数可以相同吗？至少还要对照哪两类信息？</p><p>可以。合并前的一次查找仍可能在 L1 未命中。至少要看等待来自哪一级，以及下级请求是何时开始的或有无在途合并。若要算总时间，还应考虑多个需求之间是否可以并行。</p></details><h2 id="参考文献" tabindex="-1">参考文献 <a class="header-anchor" href="#参考文献" aria-label="Permalink to &quot;参考文献&quot;">​</a></h2><ul><li><a href="https://perfmon-events.intel.com/" target="_blank" rel="noreferrer">Intel 按型号发布的性能事件表</a></li><li><a href="https://docs.kernel.org/admin-guide/perf-security.html" target="_blank" rel="noreferrer">Linux 性能事件权限</a></li><li><a href="https://man7.org/linux/man-pages/man2/perf_event_open.2.html" target="_blank" rel="noreferrer">Linux perf_event_open</a></li></ul><nav class="article-nav" aria-label="系列文章导航"><p><a href="./microarch-03a-fetch-prediction.html" class="article-nav-card article-nav-prev" rel="prev"><span class="article-nav-text"><small>上一篇</small><strong>分支预测器怎样决定下一次取指</strong></span></a></p><p><a href="./microarch-04b-observation.html" class="article-nav-card article-nav-next" rel="next"><span class="article-nav-text"><small>下一篇</small><strong>时间差何时算作侧信道证据</strong></span></a></p></nav>',27)]))}const g=a(d,[["render",i]]);export{m as __pageData,g as default};
